#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;

    Fenwick(int n) : n(n), bit(n + 1, 0) {}

    void add(int i, long long value) {
        for (; i <= n; i += i & -i)
            bit[i] += value;
    }

    long long sum(int i) const {
        long long result = 0;
        for (; i > 0; i -= i & -i)
            result += bit[i];
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    Fenwick slopes(N), intercepts(N);

    auto rangeAdd = [&](Fenwick& fw, int l, int r, long long value) {
        fw.add(l, value);
        if (r < N)
            fw.add(r + 1, -value);
    };

    for (int k = 0; k < M; ++k) {
        int type, i;
        cin >> type >> i;

        if (type == 1 || type == 2) {
            long long V;
            cin >> V;

            if (type == 1) {
                int r = min<long long>(N, i + V - 1);
                rangeAdd(slopes, i, r, -1);
                rangeAdd(intercepts, i, r, V + i);
            } else {
                int l = max<long long>(1, i - V + 1);
                rangeAdd(slopes, l, i, 1);
                rangeAdd(intercepts, l, i, V - i);
            }
        } else {
            long long slope = slopes.sum(i);
            long long intercept = intercepts.sum(i);
            cout << slope * i + intercept << '\n';
        }
    }

    return 0;
}
